// QueryServiceClient is a client for the flowrensic.v1.QueryService service.
type QueryServiceClient interface {
	ActivityStats(context.Context, *connect.Request[v1.ActivityStatsRequest]) (*connect.Response[v1.ActivityStatsResponse], error)
	ListRuns(context.Context, *connect.Request[v1.ListRunsRequest]) (*connect.Response[v1.ListRunsResponse], error)
	ListFindings(context.Context, *connect.Request[v1.ListFindingsRequest]) (*connect.Response[v1.ListFindingsResponse], error)
	// ListAlerts answers the current alerts of FPP-121, newest first.
	ListAlerts(context.Context, *connect.Request[v1.ListAlertsRequest]) (*connect.Response[v1.ListAlertsResponse], error)
	EngineMetrics(context.Context, *connect.Request[v1.EngineMetricsRequest]) (*connect.Response[v1.EngineMetricsResponse], error)
	UpdateRejections(context.Context, *connect.Request[v1.UpdateRejectionsRequest]) (*connect.Response[v1.UpdateRejectionsResponse], error)
	// ListReplayHistories picks the set CI replays and answers with every history
	// of it, in one response.
	ListReplayHistories(context.Context, *connect.Request[v1.ListReplayHistoriesRequest]) (*connect.Response[v1.ListReplayHistoriesResponse], error)
	ListReplayResults(context.Context, *connect.Request[v1.ListReplayResultsRequest]) (*connect.Response[v1.ListReplayResultsResponse], error)
	ListReplayRequests(context.Context, *connect.Request[v1.ListReplayRequestsRequest]) (*connect.Response[v1.ListReplayRequestsResponse], error)
	// ListReplaySets is how many histories the replay set of each workflow type
	// and env holds now. Main port only.
	ListReplaySets(context.Context, *connect.Request[v1.ListReplaySetsRequest]) (*connect.Response[v1.ListReplaySetsResponse], error)
	// GetReplaySet is the replay set of one workflow type in every env now, and
	// its runs in quarantine.
	GetReplaySet(context.Context, *connect.Request[v1.GetReplaySetRequest]) (*connect.Response[v1.GetReplaySetResponse], error)
	// QuarantineHistory puts a run in quarantine, so replay sets leave it out.
	// A run already there is left as it was.
	QuarantineHistory(context.Context, *connect.Request[v1.QuarantineHistoryRequest]) (*connect.Response[v1.QuarantineHistoryResponse], error)
	// ReleaseHistory takes a run out of quarantine.
	ReleaseHistory(context.Context, *connect.Request[v1.ReleaseHistoryRequest]) (*connect.Response[v1.ReleaseHistoryResponse], error)
	ListWorkflowTypes(context.Context, *connect.Request[v1.ListWorkflowTypesRequest]) (*connect.Response[v1.ListWorkflowTypesResponse], error)
	GetWorkflowType(context.Context, *connect.Request[v1.GetWorkflowTypeRequest]) (*connect.Response[v1.GetWorkflowTypeResponse], error)
	ListEphemeralRuns(context.Context, *connect.Request[v1.ListEphemeralRunsRequest]) (*connect.Response[v1.ListEphemeralRunsResponse], error)
	EphemeralRunMetrics(context.Context, *connect.Request[v1.EphemeralRunMetricsRequest]) (*connect.Response[v1.EphemeralRunMetricsResponse], error)
	WorkerMetrics(context.Context, *connect.Request[v1.WorkerMetricsRequest]) (*connect.Response[v1.WorkerMetricsResponse], error)
	// CostBreakdown counts the billable events of one namespace over two windows
	// of the configured length, broken down by workflow type, by task queue and
	// by the engine's own event type.
	CostBreakdown(context.Context, *connect.Request[v1.CostBreakdownRequest]) (*connect.Response[v1.CostBreakdownResponse], error)
	GetDeployment(context.Context, *connect.Request[v1.GetDeploymentRequest]) (*connect.Response[v1.GetDeploymentResponse], error)
	// DeployAttemptCounts keeps production traffic, the cost of a rollout and
	// the deploy's own test phase apart, for one environment.
	DeployAttemptCounts(context.Context, *connect.Request[v1.DeployAttemptCountsRequest]) (*connect.Response[v1.DeployAttemptCountsResponse], error)
	// ListThresholds is every threshold a finding is judged against, with the
	// env variable that sets it, its default and the value in force.
	ListThresholds(context.Context, *connect.Request[v1.ListThresholdsRequest]) (*connect.Response[v1.ListThresholdsResponse], error)
	// GetFinding is one stored finding by its id, not found when none is.
	GetFinding(context.Context, *connect.Request[v1.GetFindingRequest]) (*connect.Response[v1.GetFindingResponse], error)
	// SetFindingStatus archives a finding or makes it active again. A status
	// the finding already has changes nothing.
	SetFindingStatus(context.Context, *connect.Request[v1.SetFindingStatusRequest]) (*connect.Response[v1.SetFindingStatusResponse], error)
	// GetServerConfig is the config the server was started with, secrets left
	// out.
	GetServerConfig(context.Context, *connect.Request[v1.GetServerConfigRequest]) (*connect.Response[v1.GetServerConfigResponse], error)
	// GetStoredData is how much of each kind of data is stored, the time range
	// it covers and when an item of it last arrived.
	GetStoredData(context.Context, *connect.Request[v1.GetStoredDataRequest]) (*connect.Response[v1.GetStoredDataResponse], error)
	// GetCatchUp is how far the pulling of past runs after a deploy got, overall
	// and per namespace, with the backlog and the end estimate.
	GetCatchUp(context.Context, *connect.Request[v1.GetCatchUpRequest]) (*connect.Response[v1.GetCatchUpResponse], error)
	// GetLoad is the share of its capacity Flowrensic uses, overall and per job,
	// with the CPU share of each server with a CPU limit.
	GetLoad(context.Context, *connect.Request[v1.GetLoadRequest]) (*connect.Response[v1.GetLoadResponse], error)
}

